var ipAddress = "127.0.0.1"
var portList = [80, 443]

val json = """
{
    "target": $ipAddress,
    "openPorts": [
        ${portList.join(", ")}
    ],
    "timestamp": "2026-05-10T18:27:17.009Z",
    "scanMethod": "native-net"
}
""".trimIndent()

val parsedJson = jq('.').get(json)
var openPorts: Map<String, List<Integer>>? = parsedJson["openPorts"] as? Map<String, List<Integer>>
if (openPorts?.isEmpty()) {
    return "No anomalies found."
}

println("Anomalies detected.")
